$pageTitle = 'Connect. Store. Sell. Grow.';
$pageDescription = 'A digital marketplace connecting Quetta’s farmers with buyers, cold storage, and reliable transportation.';
$latestListings = fetch_all(
    'SELECT pl.id, pl.title, pl.grade, pl.quantity_available, pl.unit, pl.expected_price, l.district, pc.name AS category_name FROM produce_listings pl JOIN produce_categories pc ON pc.id = pl.category_id JOIN locations l ON l.id = pl.location_id WHERE pl.status = "active" ORDER BY pl.created_at DESC LIMIT 4'
);
$prices = fetch_all('SELECT mp.average_price, mp.unit, pc.name AS category_name, mp.price_date FROM market_prices mp JOIN produce_categories pc ON pc.id = mp.category_id ORDER BY mp.price_date DESC, mp.created_at DESC LIMIT 4');
$metrics = [
    'listings' => (int) (fetch_one('SELECT COUNT(*) AS count FROM produce_listings WHERE status = "active"')['count'] ?? 0),
    'facilities' => (int) (fetch_one('SELECT COUNT(*) AS count FROM storage_facilities WHERE status = "active"')['count'] ?? 0),
    'providers' => (int) (fetch_one('SELECT COUNT(*) AS count FROM transport_providers tp JOIN users u ON u.id = tp.user_id WHERE u.status = "active"')['count'] ?? 0),
];
require __DIR__ . '/includes/header.php';
